#include "stdafx.h"#include "HcdElementBase.h"#include <float.h>struct SDIV_P{#include "PrivateVars/DIV.h"};class KDIV : public KHcdElementBase  , protected SDIV_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _DIV("DIV", KDIV::Create);IHcdElement *KDIV::Create(){  return new KDIV;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KDIV, 4 )void KDIV::InitParm(){#include "PrivateVars/DIV.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KDIV::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;  INL0 = INU0 = 0;}void KDIV::StepCalc( SStepCalcParams &params ){  if( 0==INL0 )    OUTD0 = 0;  else    OUTD0 = INU0 / INL0;}